{
  "findings": [
    {
      "check_id": "CKV_AWS_157",
      "title": "Ensure that RDS instances have Multi-AZ enabled",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "MEDIUM",
      "explanation": "The resource explicitly sets multi_az to \"false\", which disables high availability and increases the risk of downtime during maintenance or failure."
    },
    {
      "check_id": "CKV_AWS_16",
      "title": "Ensure all data stored in the RDS is securely encrypted at rest",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "HIGH",
      "explanation": "The storage_encrypted argument is missing, meaning the database storage is not encrypted at rest by default, exposing sensitive data if physical media is compromised."
    }
  ],
  "patched_code": "resource \"aws_db_instance\" \"levelup-rds\" {\n  identifier = \"${var.ENVIRONMENT}-levelup-rds\"\n  allocated_storage = var.LEVELUP_RDS_ALLOCATED_STORAGE\n  storage_type = \"gp2\"\n  engine = var.LEVELUP_RDS_ENGINE\n  engine_version = var.LEVELUP_RDS_ENGINE_VERSION\n  instance_class = var.DB_INSTANCE_CLASS\n  backup_retention_period = var.BACKUP_RETENTION_PERIOD\n  publicly_accessible = var.PUBLICLY_ACCESSIBLE\n  username = var.LEVELUP_RDS_USERNAME\n  password = var.LEVELUP_RDS_PASSWORD\n  vpc_security_group_ids = [aws_security_group.levelup-rds-sg.id]\n  db_subnet_group_name = aws_db_subnet_group.levelup-rds-subnet-group.name\n  multi_az = true\n  storage_encrypted = true\n}",
  "fix_summary": "Enabled Multi-AZ for high availability and added storage encryption to secure data at rest."
}
